    when(ctx.getResource("/index.html")).thenReturn(new URL("file:" + FILE_PATH_INDEX_HTML_ZEPPELIN_WEB));
    when(sc.getServletContext()).thenReturn(ctx);
    IndexHtmlServlet servlet = new IndexHtmlServlet(zConf, null);
